    /**
     * Optional arguments for {@link Llm#spawn}
     *
     */
    public static class SpawnArguments {
        private List<Expertise> expertise;

        private String name;

        private String handle;

        private AgentState state;

        private String parentHandle;

        private String error;

        /**
         * Expertise to compose into the new agent's conversation. Agent arguments receive the new agent, which cannot be used until composition completes; if composition fails, the agent is left STOPPED.
         */
        public SpawnArguments withExpertise(List<Expertise> expertise) {
            this.expertise = expertise;
            return this;
        }

        /**
         * Display label for the agent — telemetry and error messages; carries no identity. Defaults to a short name derived from the conversation.
         */
        public SpawnArguments withName(String name) {
            this.name = name;
            return this;
        }

        /**
         * The runtime handle to restore the instance under, as published on its loop span as dagger.io/agent.id. Omit to mint a fresh instance.
         */
        public SpawnArguments withHandle(String handle) {
            this.handle = handle;
            return this;
        }

        /**
         * The lifecycle state to create the agent in, as facts on the entry: IDLE is ready to be prompted, PAUSED parks it, FAILED holds an error a resume retries past, STOPPED preserves a dormant snapshot that send or resume can relaunch.<br/><br/>RUNNING and WAITING_INPUT are refused: they describe a loop, and a restored loop died with the session that published it — restore such an agent as IDLE, its interrupted turn's input still pending on the conversation.
         */
        public SpawnArguments withState(AgentState state) {
            this.state = state;
            return this;
        }

        /**
         * Recorded parent handle when restoring an agent. Lineage does not install a notification subscription. Requires a supplied handle. The parent must already be restored in this session and cannot be the agent itself or its descendant.
         */
        public SpawnArguments withParentHandle(String parentHandle) {
            this.parentHandle = parentHandle;
            return this;
        }

        /**
         * The loop error to create the agent with, for state FAILED. Refused with any other state.
         */
        public SpawnArguments withError(String error) {
            this.error = error;
            return this;
        }

        Arguments toArguments() {
            Arguments.Builder builder = Arguments.newBuilder();
            if (expertise != null) {
                builder.add("expertise", this.expertise);
            }

            if (name != null) {
                builder.add("name", this.name);
            }

            if (handle != null) {
                builder.add("handle", this.handle);
            }

            if (state != null) {
                builder.add("state", this.state);
            }

            if (parentHandle != null) {
                builder.add("parentHandle", this.parentHandle);
            }

            if (error != null) {
                builder.add("error", this.error);
            }

                    return builder.build();
        }
    }

